pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 t) public {
        vm.assume(actor != address(0));
        t = bound(t, 1, type(uint64).max);

        vm.deal(actor, 20 ether);

        uint256 before = c.pastBlockTime();
        uint256 warpTime = (t > before) ? t : before + 1;
        vm.warp(warpTime);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call reverted");

        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}
